const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const connectionDefaults={demo:{baseUrl:'http://localhost:11434',model:'qwen3:8b'},ollama:{baseUrl:'http://localhost:11434',model:'qwen3:8b'},compatible:{baseUrl:'http://localhost:1234/v1',model:'local-model'},mimo:{baseUrl:'https://token-plan-cn.xiaomimimo.com/v1',model:'mimo-v2.6-pro'}};
export function connectionSettings(s){
  const regions=[['cn','中国'],['sgp','新加坡'],['ams','欧洲']];
  return `<div class="page-heading"><div><div class="eyebrow">CONNECTIONS</div><h1>模型设置</h1><p>支持 Ollama、兼容 API 和 MiMo Token Plan，选题讨论与辩论共用连接。</p></div></div><form id="settings-form" class="form-card settings-card"><h2>模型配置</h2><div class="form-grid"><label>运行模式<select name="provider" id="provider">${[['demo','演示模式 · 无需密钥'],['ollama','Ollama · 本地模型'],['compatible','兼容 API · 云端或本地'],['mimo','MiMo Token Plan · 套餐专属接口']].map(([v,n])=>`<option value="${v}" ${s.provider===v?'selected':''}>${n}</option>`).join('')}</select></label><label>模型名称<input name="model" required maxlength="100" value="${esc(s.model)}" placeholder="例如 mimo-v2.6-pro"></label><label class="full" id="mimo-region-label" ${s.provider==='mimo'?'':'hidden'}>MiMo 集群<select id="mimo-region">${regions.map(([v,n])=>`<option value="${v}" ${s.baseUrl.includes(`token-plan-${v}.`)?'selected':''}>${n}集群</option>`).join('')}</select><small>请选择与你的 Token Plan 控制台一致的集群。也可直接粘贴控制台专属地址。</small></label><label class="full">服务地址<input name="baseUrl" type="url" required value="${esc(s.baseUrl)}"><small>Ollama 填服务地址；兼容 API 填基础地址。粘贴完整 /chat/completions 也会自动规范化。</small></label><label class="full">模型 API Key<input name="apiKey" type="password" autocomplete="off" placeholder="${s.hasApiKey?'已配置；相同连接留空保留':s.provider==='mimo'?'tp-… 或 ttp-…':'本地 Ollama 通常不需要'}"><small>留空仅在提供商与地址不变时保留原密钥，输入 - 清除。密钥只保留于服务端内存，重启可通过环境变量恢复。</small></label></div><div id="mimo-help" class="notice" ${s.provider==='mimo'?'':'hidden'}>MiMo Token Plan 使用套餐专属 Base URL 与 tp-/ttp- 密钥，和按量付费接口分开。此处采用 api-key 认证。模型名称请按套餐权限填写。<a href="https://mimo.mi.com/docs/zh-CN/tokenplan/Token%20Plan/quick-access" target="_blank" rel="noopener noreferrer">查看官方接入说明 ↗</a></div><h2 class="form-subtitle">联网研究</h2><label>Tavily API Key <span class="optional">可选</span><input name="tavilyKey" type="password" autocomplete="off" placeholder="${s.hasTavilyKey?'已配置，留空保留':'tvly-…'}"><small>配置后使用全网搜索；留空使用免密钥维基百科检索。</small></label><div class="form-actions"><button class="primary" type="submit">保存连接</button><button class="secondary" id="test-connection" type="button">测试已保存连接 ↗</button></div><p id="connection-result" role="status"></p><section class="search-test"><h2>测试搜索</h2><small>检索自动使用 Windows 系统代理；无需模型调用。</small><div><input id="search-test-query" maxlength="300" value="人工智能" aria-label="搜索测试关键词"><button type="button" class="secondary" id="test-search">搜索</button></div><div id="search-test-results" role="status"></div></section></form>`;
}
